def header(active=None,role=None):
    if role in ('student','teacher','player'):
        if role=='student': menus=['Dashboard','Assignments','Results','Help']; act=active or 'Dashboard'
        elif role=='teacher': menus=['Classes','Assignments','Reports','Library']; act=active or 'Classes'
        else: menus=[];act=''
        middle=''.join(f'<span class="nav-link {"selected" if a==act else ""}">{a}</span>' for a in menus)
        if role=='player':
            return '<div class="nav" style="height:72px"><div class="nav-logo"><img src="../assets/G1_CANONICAL_LOGO_FROM_APPROVED_SCREENSHOT.png"/></div><div class="nav-menu" style="margin-left:50px"><span class="nav-link" style="color:#54778e">Class 10 · Chemistry</span></div><div class="nav-end" style="margin-left:auto"><span class="lang">English / తెలుగు ⌄</span><span class="btn outline" style="min-height:39px">Exit lab</span></div></div>'
        return f'<div class="nav"><div class="nav-logo"><img src="../assets/G1_CANONICAL_LOGO_FROM_APPROVED_SCREENSHOT.png"/></div><div class="nav-menu">{middle}</div><div class="nav-end"><span class="lang">English / తెలుగు ⌄</span><span class="role">{role.capitalize()} account</span></div></div>'
    menu=[('Laboratories','Laboratories'),('For teachers','For teachers'),('Help','Help')]
    mid=''.join(f'<span class="nav-link {"selected" if a==active else ""}">{a}</span>' for a,b in menu)
    return f'<div class="nav"><div class="nav-logo"><img src="../assets/G1_CANONICAL_LOGO_FROM_APPROVED_SCREENSHOT.png"/></div><div class="nav-menu">{mid}</div><div class="nav-end"><span class="lang">English / తెలుగు ⌄</span><span class="btn outline" style="min-height:41px">Sign in</span></div></div>'

def full(inner,active=None,role=None):
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"/><title>G1 Virtua Labs — Visual reference</title><style>'+CSS+'</style></head><body>'+header(active,role)+'<div class="page">'+inner+'</div></body></html>'

